package dev.zomboid.mts;
import java.util.*;import minecrafttransportsimulator.entities.instances.*;import minecrafttransportsimulator.mcinterface.InterfaceManager;import minecrafttransportsimulator.items.instances.ItemItem;import minecrafttransportsimulator.packets.instances.PacketEntityInteract;
public class FamilyGuiChecks {
 static int n;static void check(boolean b,String msg){n++;if(!b)throw new AssertionError(msg);}
 public static class Held extends Checks.Held {public Object item=new ItemItem();public Object getItem(){return item;}}
 public static class Player extends InspectionChecks.Player {public Held stack=new Held();public Held getHeldStack(){return stack;}}
 public static void main(String[] args){EntityVehicleF_Physics heli=new EntityVehicleF_Physics();heli.definition.systemName="bell47g";heli.definition.motorized.isAircraft=true;Checks.Slot slot=new Checks.Slot();slot.types.add("engine_helicopter_flat");heli.definition.parts.add(slot);PartEngine engine=new PartEngine();engine.vehicleOn=heli;engine.damageVar.currentValue=50;engine.collisionBoxes.add(new Checks.Box());heli.partsInSlots.add(engine);heli.engines.add(engine);Player player=new Player();InterfaceManager.clientInterface.player=player;Object gui=R.make("dev.zomboid.mts.CheckGUI",heli);R.call(gui,"setupComponents");R.call(gui,"setStates");FamilyWorkshop.View view=FamilyWorkshop.views.get(gui);check(view!=null&&view.buttons.size()==8,"actual generated GUI routes to helicopter workshop");check(R.call(gui,"getTexture").toString().contains("helicopter"),"generated GUI selects helicopter texture");check(R.get(view.buttons.get(1),"text").toString().contains("Motor"),"component buttons show native engine");FamilyWorkshop.action(gui,"service-select:1");check(view.selected==1,"component selection works");FamilyWorkshop.action(gui,"service-repair");check(InterfaceManager.packetInterface.packets.size()==2,"repair goes through press and release native packets");PacketEntityInteract packet=(PacketEntityInteract)InterfaceManager.packetInterface.packets.get(0);check(packet.entity==engine&&packet.rightClick,"repair targets selected engine, not whole craft");engine.running=true;FamilyWorkshop.action(gui,"service-repair");check(InterfaceManager.packetInterface.packets.size()==2,"running engine cannot repair from GUI");check(FamilyWorkshop.blockRepair(new ItemItem(),engine,player,true),"server repair guard blocks running engine");engine.running=false;check(!FamilyWorkshop.blockRepair(new ItemItem(),engine,player,true),"server repair guard allows stopped compatible interaction");R.call(gui,"close");check(!FamilyWorkshop.views.containsKey(gui),"GUI close removes state");System.out.println("Family GUI checks: "+n);}
}
